const data = $input.first().json.body || {};

const action = data.action || "updated";
const repository = data.repository || "unknown/repo";
const prNumber = data.pr_number || "?";
const title = data.title || "Untitled PR";
const url = data.url || "";
const author = data.author || data.sender || "unknown";
const base = data.base || "main";
const head = data.head || "unknown";
const isDraft = data.draft === true;
const merged = data.merged === true;
const labels = Array.isArray(data.labels) ? data.labels.map(l => typeof l === "string" ? l : l.name).filter(Boolean) : [];
const reviewers = Array.isArray(data.requested_reviewers) ? data.requested_reviewers.map(r => typeof r === "string" ? r : r.login).filter(Boolean) : [];

const statusMap = {
  opened: { color: 3447003, label: "🟢 PR opened" },
  reopened: { color: 10181046, label: "🟡 PR reopened" },
  ready_for_review: { color: 5763719, label: "👀 Ready for review" },
  synchronize: { color: 9807270, label: "🔄 New commits pushed" },
  closed: { color: merged ? 5763719 : 15158332, label: merged ? "🟣 PR merged" : "🔴 PR closed" },
};

const status = statusMap[action] || { color: 9807270, label: `ℹ️ ${action}` };

const fields = [
  { name: "Repository", value: repository, inline: true },
  { name: "Author", value: author, inline: true },
  { name: "PR", value: `#${prNumber}`, inline: true },
  { name: "Branches", value: `\`${head}\` → \`${base}\``, inline: false },
  { name: "Status", value: isDraft ? `${status.label} • Draft` : status.label, inline: true },
];

if (labels.length) {
  fields.push({ name: "Labels", value: labels.map(l => `\`${l}\``).join(", "), inline: false });
}

if (reviewers.length) {
  fields.push({ name: "Requested reviewers", value: reviewers.map(r => `@${r}`).join(", "), inline: false });
}

return [{
  json: {
    embeds: [
      {
        title: `PR #${prNumber} — ${title}`,
        url,
        description: `**${status.label}** in **${repository}**`,
        color: status.color,
        fields,
        footer: { text: "n8n demo • GitHub PR lifecycle" },
        timestamp: new Date().toISOString()
      }
    ]
  }
}];

const data = $input.first().json.body || {};

return [{
  json: {
    embeds: [
      {
        title: `💬 New PR comment on #${data.pr_number}`,
        url: data.comment_url || data.url || "",
        description: `**${data.sender || data.author || "Someone"}** commented on **${data.repository || "unknown/repo"}**`,
        color: 16098851,
        fields: [
          { name: "Title", value: data.title || "Untitled PR", inline: false },
          { name: "Comment", value: (data.comment_body || "_No comment text_").slice(0, 1000), inline: false }
        ],
        footer: { text: "n8n demo • PR conversation comment" },
        timestamp: new Date().toISOString()
      }
    ]
  }
}];

const data = $input.first().json.body || {};

return [{
  json: {
    embeds: [
      {
        title: `🧵 Inline review comment on PR #${data.pr_number}`,
        url: data.comment_url || data.url || "",
        description: `**${data.sender || data.author || "Someone"}** left a code comment in **${data.repository || "unknown/repo"}**`,
        color: 15548997,
        fields: [
          { name: "Title", value: data.title || "Untitled PR", inline: false },
          { name: "Comment", value: (data.comment_body || "_No comment text_").slice(0, 1000), inline: false }
        ],
        footer: { text: "n8n demo • Inline review comment" },
        timestamp: new Date().toISOString()
      }
    ]
  }
}];

const data = $input.first().json.body || {};

const reviewState = data.review_state || data.action || "submitted";

const reviewMap = {
  approved: { color: 5763719, label: "✅ Review approved" },
  changes_requested: { color: 15158332, label: "❌ Changes requested" },
  commented: { color: 16098851, label: "💬 Review submitted" },
};

const review = reviewMap[reviewState] || { color: 9807270, label: `ℹ️ Review ${reviewState}` };

const fields = [
  { name: "PR", value: `#${data.pr_number || "?"}`, inline: true },
  { name: "Repository", value: data.repository || "unknown/repo", inline: true },
  { name: "Reviewer", value: data.author || data.sender || "unknown", inline: true },
  { name: "Title", value: data.title || "Untitled PR", inline: false },
  { name: "Review state", value: reviewState, inline: true }
];

if (data.comment_body) {
  fields.push({ name: "Review note", value: data.comment_body.slice(0, 1000), inline: false });
}

return [{
  json: {
    embeds: [
      {
        title: `${review.label} on PR #${data.pr_number}`,
        url: data.url || "",
        description: `Review event in **${data.repository || "unknown/repo"}**`,
        color: review.color,
        fields,
        footer: { text: "n8n demo • PR review" },
        timestamp: new Date().toISOString()
      }
    ]
  }
}];
